// ignore_for_file: unused_element, unnecessary_cast

import 'dataflow_endpoint_mqtt_authentication_response.dart';
import 'tls_properties_response.dart';

/// Broker endpoint properties
class DataflowEndpointMqttResponse {
  /// authentication properties. DEFAULT: kubernetes.audience=aio-internal. NOTE - Enum field only property is allowed
  final DataflowEndpointMqttAuthenticationResponse authentication;
  /// Client ID prefix. Client ID generated by the dataflow is <prefix>-TBD. Optional; no prefix if omitted.
  final String? clientIdPrefix;
  /// Cloud event mapping config.
  final String? cloudEventAttributes;
  /// Host of the Broker in the form of <hostname>:<port>. Optional; connects to Broker if omitted.
  final String? host;
  /// Broker KeepAlive for connection in seconds.
  final int? keepAliveSeconds;
  /// The max number of messages to keep in flight. For subscribe, this is the receive maximum. For publish, this is the maximum number of messages to send before waiting for an ack.
  final int? maxInflightMessages;
  /// Enable or disable websockets.
  final String? protocol;
  /// Qos for Broker connection.
  final int? qos;
  /// Whether or not to keep the retain setting.
  final String? retain;
  /// Session expiry in seconds.
  final int? sessionExpirySeconds;
  /// TLS configuration.
  final TlsPropertiesResponse? tls;

  /// Creates a new [DataflowEndpointMqttResponse].
  /// [authentication] authentication properties. DEFAULT: kubernetes.audience=aio-internal. NOTE - Enum field only property is allowed
  /// [clientIdPrefix] Client ID prefix. Client ID generated by the dataflow is <prefix>-TBD. Optional; no prefix if omitted.
  /// [cloudEventAttributes] Cloud event mapping config.
  /// [host] Host of the Broker in the form of <hostname>:<port>. Optional; connects to Broker if omitted.
  /// [keepAliveSeconds] Broker KeepAlive for connection in seconds.
  /// [maxInflightMessages] The max number of messages to keep in flight. For subscribe, this is the receive maximum. For publish, this is the maximum number of messages to send before waiting for an ack.
  /// [protocol] Enable or disable websockets.
  /// [qos] Qos for Broker connection.
  /// [retain] Whether or not to keep the retain setting.
  /// [sessionExpirySeconds] Session expiry in seconds.
  /// [tls] TLS configuration.
  DataflowEndpointMqttResponse({
    required this.authentication,
    this.clientIdPrefix,
    this.cloudEventAttributes,
    this.host,
    this.keepAliveSeconds,
    this.maxInflightMessages,
    this.protocol,
    this.qos,
    this.retain,
    this.sessionExpirySeconds,
    this.tls,
  });

  Map<String, dynamic> toMap() {
    return <String, dynamic>{
      'authentication': authentication.toMap(),
      'clientIdPrefix': ?clientIdPrefix,
      'cloudEventAttributes': ?cloudEventAttributes,
      'host': ?host,
      'keepAliveSeconds': ?keepAliveSeconds,
      'maxInflightMessages': ?maxInflightMessages,
      'protocol': ?protocol,
      'qos': ?qos,
      'retain': ?retain,
      'sessionExpirySeconds': ?sessionExpirySeconds,
      'tls': ?tls == null ? null : tls!.toMap(),
    };
  }

  factory DataflowEndpointMqttResponse.fromMap(Map<String, dynamic> map) {
    return DataflowEndpointMqttResponse(
      authentication: DataflowEndpointMqttAuthenticationResponse.fromMap((map['authentication'] as Map).cast<String, dynamic>()),
      clientIdPrefix: map['clientIdPrefix'] == null ? null : map['clientIdPrefix'] as String,
      cloudEventAttributes: map['cloudEventAttributes'] == null ? null : map['cloudEventAttributes'] as String,
      host: map['host'] == null ? null : map['host'] as String,
      keepAliveSeconds: map['keepAliveSeconds'] == null ? null : map['keepAliveSeconds'] as int,
      maxInflightMessages: map['maxInflightMessages'] == null ? null : map['maxInflightMessages'] as int,
      protocol: map['protocol'] == null ? null : map['protocol'] as String,
      qos: map['qos'] == null ? null : map['qos'] as int,
      retain: map['retain'] == null ? null : map['retain'] as String,
      sessionExpirySeconds: map['sessionExpirySeconds'] == null ? null : map['sessionExpirySeconds'] as int,
      tls: map['tls'] == null ? null : TlsPropertiesResponse.fromMap((map['tls'] as Map).cast<String, dynamic>()),
    );
  }
}

